t-collection:check\": \"node scripts/check-test-collection.mjs --self-test && node scripts/check-test-collection.mjs\",\n    \"toolchain:check\": \"node scripts/check-toolchain-pins.mjs --self-test && node scripts/check-toolchain-pins.mjs\",\n    \"engines:check\": \"node scripts/check-engine-strict.mjs --self-test && node scripts/check-engine-strict.mjs\",\n    \"issue-forms:check\": \"node scripts/check-issue-forms.mjs --self-test && node scripts/check-issue-forms.mjs\",\n    \"i18n:check\": \"node scripts/check-i18n.mjs --self-test && node scripts/check-i18n.mjs\",\n    \"no-public-ip:check\": \"node scripts/check-no-public-ip.mjs --self-test && node scripts/check-no-public-ip.mjs\",\n    \"no-public-ip:message\": \"node scripts/check-no-public-ip.mjs\",\n    \"internal-ids:check\": \"node scripts/check-internal-identifiers.mjs --self-test && node scripts/check-internal-identifiers.mjs\",\n    \"internal-ids:message\": \"node scripts/check-internal-identifiers.mjs\",\n    \"readme-facts:check\": \"node scripts/check-readme-facts.mjs --self-test && node scripts/check-readme-facts.mjs\",\n    \"readme-structure:check\": \"node scripts/check-readme-structure.mjs\",\n    \"release:publish\": \"node scripts/release-publish-tag.mjs\",\n    \"release:preflight\": \"node scripts/release-publish-tag.mjs --preflight\"\n  },\n  \"devDependencies\": {\n    \"@vitest/coverage-v8\": \"3.2.7\",\n    \"typescript\": \"~5.9.3\",\n    \"vitest\": \"^3.2.7\",\n    \"yaml\": \"^2.9.1\"\n  },\n  \"packageManager\": \"pnpm@10.30.3\",\n  \"engines\": {\n    \"node\": \">=22.19.0\",\n    \"pnpm\": \">=10\"\n  },\n  \"license\": \"Apache-2.0\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/hyzyn/dsh-plugin-kit.git\"\n  },\n  \"homepage\": \"https://github.com/hyzyn/dsh-plugin-kit#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/hyzyn/dsh-plugin-kit/issues\"\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"README.md\"\n  ],\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"dependencies\": {\n    \"@hyzyn/dsh-codegraph\": \"0.6.20\",\n    \"@hyzyn/dsh-docker\": \"0.15.0\",\n    \"@hyzyn/dsh-env\": \"0.3.17\",\n    \"@hyzyn/dsh-kit-settings\": \"0.2.9\",\n    \"@hyzyn/dsh-loglens\": \"0.1.8\",\n    \"@hyzyn/dsh-mcp\": \"0.3.13\",\n    \"@hyzyn/dsh-profile\": \"0.2.15\",\n    \"@hyzyn/dsh-prompt\": \"0.2.15\",\n    \"@hyzyn/dsh-rss\": \"0.4.16\",\n    \"@hyzyn/dsh-search\": \"0.4.18\",\n    \"@hyzyn/dsh-tty\": \"0.38.0\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh\": \"^0.1.7-rc.2 || ^0.2.0-rc.1 || ^0.2.0-rc.2 || ^0.2.1-alpha.1 || ^0.2.1-alpha.2 || ^0.2.1-alpha.5 || ^0.2.1-rc.1 || ^0.2.1-rc.2 || ^0.2.1-rc.3 || ^0.2.1-rc.4 || ^0.2.1-rc.5 || ^0.2.2-alpha.3 || ^0.2.2-rc.1\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh\": {\n      \"optional\": true\n    }\n  },\n  \"pnpm\": {\n    \"overrides\": {\n      \"@deepseek-ai/dsh\": \"link:scripts/dsh-peer-stub\"\n    }\n  }\n}\n"
