,\n      'msg.addSkipped': ', skipped {count} already subscribed',\n      'msg.addedSaving': 'Added {added} feeds{skipped}, saving…',\n      'msg.catalogExists': 'That catalog already exists',\n      'msg.catalogAdded': 'Catalog added, saving…',\n      'msg.catalogRemoved': 'Catalog removed, saving…',\n      'msg.confirmDiscard': 'Discard unsaved changes and reload?',\n      'msg.opmlTitle': 'DSH RSS subscriptions',\n      'error.catalogNameRequired': 'Enter a catalog name',\n      'error.catalogUrlRequired': 'Enter the OPML catalog URL',\n      'error.catalogUrlInvalid': 'Invalid catalog URL',\n    }\n    /* ==== dsh-i18n:end ==== */\n\n    /** 占位符替换：`{name}` → params.name（缺参留空，不抛错——文案不该打死界面）。 */\n    function i18nFormat(text, params) {\n      if (params === undefined) return text\n      return String(text).replace(/\\{(\\w+)\\}/g, (_match, name) => (params[name] === undefined ? '' : String(params[name])))\n    }\n\n    /** 中文兜底：老宿主（DSH ≤0.1.5）没有 locale 服务时，界面不能变成一串键名。 */\n    function i18nFallback(key, params) {\n      return i18nFormat(I18N_ZH[key] !== undefined ? I18N_ZH[key] : key, params)\n    }\n\n    let t = i18nFallback\n\n    /**\n     * 注册目录并绑定翻译函数。**动态 inject**：老宿主上回调永不触发、`t` 保持中文兜底；\n     * 写成静态 `inject: ['locale']` 会让整张卡片在老宿主上根本不挂。\n     *\n     * 语言切换不用自己订阅：插槽 outlet 随 locale revision 重渲染（renderer 的\n     * `useLocaleRevision`），而 `bind()` 返回的翻译函数在**调用时**读当前语言。\n     */\n    function installI18n(ctx) {\n      ctx.inject(['locale'], (i18nCtx) => {\n        const disposeZh = i18nCtx.locale.register(I18N_NS, 'zh', I18N_ZH)\n        const disposeEn = i18nCtx.locale.register(I18N_NS, 'en', I18N_EN)\n        t = i18nCtx.locale.bind(I18N_NS)\n        return () => {\n          disposeEn()\n          disposeZh()\n          t = i18nFallback\n        }\n      })\n    }\n\n    /* ================================ 面板状态 ================================ */\n\n    const state = {\n      digest: null,\n      config: null,\n      builtins: BUILTIN_CHANNELS,\n      newCategory: '',\n      loading: false,\n      refreshing: false,\n      /** 刷新超过消抖阈值（180ms）才置真：卡片上的过渡层只在慢刷新时出现，避免闪一下。 */\n      refreshSlow: false,\n      saving: false,\n      modalLoading: false,\n      modalSlow: false,\n      error: '',\n      dirty: false,\n      catalogQuery: '',\n      catalogCategory: '',\n      catalogEntries: [],\n      catalogCategories: [],\n      catalogLoading: false,\n      catalogError: '',\n      catalogDisabled: false,\n      catalogSelected: new Set(),\n      catalogSource: '',\n      catalogSources: [],\n      catalogBuiltin: null,\n      catalogNewName: '',\n      catalogNewUrl: '',\n      catalogOpen: false,\n      customQuery: '',\n      modalQuery: '',\n      modalCategory: '',\n      modalOpener: null,\n      importOpen: false,\n      importText: '',\n    }\n\n    let panelEl\n    let modalEl\n    let catalogModalEl\n    let toastEl\n    let toastTimer\n    let saveTimer\n    let dragIndex = null\n\n    /* ================================ Toast ================================ */\n\n    const TOAST_ICONS = { ok: '✓', error: '✕', info: 'ⓘ' }\n\n    function toast(message, kind) {\n      if (toastEl !== undefined) toastEl.remove()\n      toastEl = document.createElement('div')\n      toastEl.className = 'rss_toast'\n      toastEl.setAttribute('role', 'status')\n      toastEl.dataset.kind = kind || 'info'\n      const icon = TOAST_ICONS[kind || 'info'] || ''\n      toastEl.innerHTML = (icon ? '<span class=\"rss_toastIcon\">' + icon + '</span>' : '') + '<span>' + esc(message) + '</span>'\n      document.body.appendChild(toastEl)\n      clearTimeout(toastTimer)\n      toastTimer = setTimeout(() => {\n        toastEl.remove()\n        toastEl = undefined\n      }, 3200)\n    }\n\n    /* ================================ 区块渲染 ================================ */\n\n    function categoryOptions(selected) {\n      const options = new Set(state.config?.categories || [])\n      if (selected) options.add(selected)\n      let html = '<option value=\"\">' + t('panel.uncategorized') + '</option>'\n      for (const category of options) {\n        html += '<option value=\"' + esc(category) + '\"' + (category === selected ? ' selected' : '') + '>' + esc(category) + '</option>'\n      }\n      return html\n    }\n\n    function catalogCategoryOptions() {\n      const selected = state.catalogCategory || ''\n      let html = '<option value=\"\">' + t('panel.allCategories') + '</option>'\n      for (const cat of state.catalogCategories || []) {\n        html += '<option value=\"' + esc(cat) + '\"' + (cat === selected ? ' selected' : '') + '>' + esc(cat) + '</option>'\n      }\n      return html\n    }\n\n    function catalogSourceOptions() {\n      const selected = state.catalogSource || ''\n      let html = '<option value=\"\">' + t('panel.allSources') + '</option>'\n      const builtin = state.catalogBuiltin\n      if (builtin && builtin.enabled) {\n        html += '<option value=\"' + esc(builtin.name || 'awesome-rsshub-routes') + '\"' + (selected === builtin.name ? ' selected' : '') + '>' + esc(builtin.name || 'awesome-rsshub-routes') + '</option>'\n      }\n      for (const source of state.catalogSources || []) {\n        const value = source.name\n        html += '<option value=\"' + esc(value) + '\"' + (selected === value ? ' selected' : '') + '>' + esc(value) + '</option>'\n      }\n      return html\n    }\n\n    function catalogRoot() {\n      if (catalogModalEl !== undefined && catalogModalEl.isConnected) return catalogModalEl\n      return panelEl\n    }\n\n    function updateCatalogSources() {\n      const root = catalogRoot()\n      const node = root !== undefined ? root.querySelector('#rss-catalog-sources') : null\n      if (node === null) return\n      node.outerHTML = '<div id=\"rss-catalog-sources\">' + renderCatalogSourcesBlock() + '</div>'\n    }\n\n    function builtinOf(source) {\n      if (!source) return null\n      for (const builtin of state.builtins || []) {\n        if ((source.builtin && source.builtin === builtin.key) || source.url === builtin.url || source.name === builtin.name) return builtin\n      }\n      return null\n    }\n\n    function findBuiltinSource(builtin) {\n      return (state.config?.sources || []).find((source) => builtinOf(source)?.key === builtin.key) || null\n    }\n\n    function channelListHtml() {\n      const query = (state.customQuery || '').trim().toLowerCase()\n      const sources = state.config?.sources || []\n      const urlCount = new Map()\n      for (const source of sources) {\n        const key = (source.url || '').trim().toLowerCase()\n        urlCount.set(key, (urlCount.get(key) || 0) + 1)\n      }\n      const enabled = []\n      for (let i = 0; i < sources.length; i++) {\n        const source = sources[i]\n        const builtin = builtinOf(source)\n        if (!query || (source.name || '').toLowerCase().includes(query) || (source.url || '').toLowerCase().includes(query)) {\n          enabled.push({\n            source,\n            index: i,\n            builtin,\n            dup: urlCount.get((source.url || '').trim().toLowerCase()) > 1,\n          })\n        }\n      }\n      const disabledBuiltins = (state.builtins || [])\n        .filter((builtin) => findBuiltinSource(builtin) === null)\n        .filter((builtin) => !query || (builtin.name || '').toLowerCase().includes(query) || (builtin.url || '').toLowerCase().includes(query))\n      if (enabled.length === 0 && disabledBuiltins.length === 0) {\n        return '<div class=\"rss_empty\">' + t('list.emptyChannels') + '</div>'\n      }\n      const parts = []\n      parts.push('<div class=\"rss_channelList\" id=\"rss-channel-list\">')\n      for (const row of enabled) parts.push(renderChannelRow(row))\n      if (disabledBuiltins.length > 0) {\n        parts.push('<div class=\"rss_disabledTitle\">' + t('panel.disabledBuiltins') + '</div>')\n        for (const builtin of disabledBuiltins) parts.push(renderDisabledBuiltinRow(builtin))\n      }\n      // 慢刷新：进度条贴分类行下沿（列表区顶部那条线），胶囊骑在线上、水平居中\n      // 注意 digest 必须从 state 取：这里原先直接引用了一个未绑定的 `digest`，\n      // 于是只要渲染到这一行就 ReferenceError（整张设置卡片挂掉）。见 scripts/client-lint.mjs 第 4 条。\n      const digest = state.digest\n      if (digest && state.modalLoading && state.modalSlow) parts.push(busyBarHtml() + busyPillHtml(digest))\n      parts.push('</div>')\n      return parts.join('')\n    }\n\n    function renderChannelRow(row) {\n      const { source, index, builtin, dup } = row\n      if (builtin) {\n        const category = source.category?.trim() || builtin.category\n        return '<div class=\"rss_channelRow rss_builtinRow\" data-channel-index=\"' + index + '\">' +\n          '<span class=\"rss_dragHandle\" draggable=\"true\" data-drag-index=\"' + index + '\" role=\"img\" aria-label=\"' + esc(t('btn.dragToSort')) + '\" title=\"' + esc(t('btn.dragToSort')) + '\">' + ICON_GRIP + '</span>' +\n          '<input type=\"checkbox\" data-action=\"builtin-toggle\" data-key=\"' + esc(builtin.key) + '\" checked />' +\n          '<span class=\"rss_channelName\" title=\"' + esc(builtin.name) + '\">' + esc(builtin.name) + '</span>' +\n          '<span class=\"rss_channelUrl\" title=\"' + esc(builtin.url) + '\">' + esc(builtin.url) + '</span>' +\n          '<select class=\"rss_input rss_builtinCategory\" data-field=\"rss-builtin-category\" data-key=\"' + esc(builtin.key) + '\">' + categoryOptions(category) + '</select>' +\n          '<span class=\"rss_channelType\">' + t('panel.builtin') + '</span>' +\n          '<span></span>' +\n          '</div>'\n      }\n      return '<div class=\"rss_channelRow' + (dup ? ' rss_dupRow' : '') + '\" data-channel-index=\"' + index + '\">' +\n        '<span class=\"rss_dragHandle\" draggable=\"true\" data-drag-index=\"' + index + '\" role=\"img\" aria-label=\"' + esc(t('btn.dragToSort')) + '\" title=\"' + esc(t('btn.dragToSort')) + '\">' + ICON_GRIP + '</span>' +\n        '<span></span>' +\n        '<input class=\"rss_input\" data-field=\"rss-source-name\" data-index=\"' + index + '\" value=\"' + esc(source.name || '') + '\" placeholder=\"' + esc(t('placeholder.name')) + '\" />' +\n        '<input class=\"rss_input\" data-field=\"rss-source-url\" data-index=\"' + index + '\" value=\"' + esc(source.url || '') + '\" placeholder=\"RSS/Atom URL\" spellcheck=\"false\" />' +\n        '<select class=\"rss_input\" data-field=\"rss-source-category\" data-index=\"' + index + '\">' + categoryOptions(source.category) + '</select>' +\n        '<span class=\"rss_channelType\">' + t('panel.custom') + '</span>' +\n        '<button class=\"rss_btnGhost rss_btnDanger\" data-action=\"config-remove-source\" data-index=\"' + index + '\">' + t('btn.delete') + '</button>' +\n        '</div>'\n    }\n\n    function renderDisabledBuiltinRow(builtin) {\n      return '<div class=\"rss_channelRow rss_builtinRow\" data-disabled=\"true\">' +\n        '<span class=\"rss_dragHandle\" aria-hidden=\"true\" style=\"visibility:hidden\">' + ICON_GRIP + '</span>' +\n        '<input type=\"checkbox\" data-action=\"builtin-toggle\" data-key=\"' + esc(builtin.key) + '\" />' +\n        '<span class=\"rss_channelName\" title=\"' + esc(builtin.name) + '\">' + esc(builtin.name) + '</span>' +\n        '<span class=\"rss_channelUrl\" title=\"' + esc(builtin.url) + '\">' + esc(builtin.url) + '</span>' +\n        '<span class=\"rss_channelType\">' + t('panel.builtin') + '</span>' +\n        '<span></span><span></span>' +\n        '</div>'\n    }\n\n    function renderChannelsSection() {\n      const all = state.config?.sources || []\n      const parts = []\n      parts.push('<div class=\"rss_settingSection\" id=\"rss-sec-channels\">')\n      parts.push('<div class=\"rss_settingTitle\">' + t('panel.channels') + '</div>')\n      parts.push('<div class=\"rss_settingHint\">' + t('panel.channelsHint') + '</div>')\n      parts.push('<div class=\"rss_addRow\" id=\"rss-custom-tools\">')\n      parts.push('<input class=\"rss_input\" data-field=\"rss-custom-query\" value=\"' + esc(state.customQuery) + '\" placeholder=\"' + esc(t('placeholder.filterChannels')) + '\" autocomplete=\"off\" spellcheck=\"false\" />')\n      parts.push('<span class=\"rss_customCount\">' + t('panel.channelCount', { count: all.length }) + '</span>')\n      parts.push('<button class=\"rss_btnGhost\" data-action=\"config-add-source\">' + t('btn.addSource') + '</button>')\n      parts.push('</div>')\n      parts.push('<div class=\"rss_customImport\">')\n      parts.push('<input type=\"file\" id=\"rss-import-file\" data-field=\"rss-import-file\" accept=\".opml,.xml,text/xml,application/xml\" style=\"display:none\" />')\n      parts.push('<button class=\"rss_btnGhost\" data-action=\"custom-import-opml\">' + t('btn.importOpml') + '</button>')\n      parts.push('<button class=\"rss_btnGhost\" data-action=\"custom-import-paste\">' + (state.importOpen ? t('btn.hidePasteImport') : t('btn.pasteUrlList')) + '</button>')\n      parts.push('<button class=\"rss_btnGhost\" data-action=\"custom-export-opml\">' + t('btn.exportOpml') + '</button>')\n      parts.push('<button class=\"rss_btnGhost\" data-action=\"catalog-open\">' + t('btn.feedCatalog') + '</button>')\n      parts.push('<span class=\"rss_customImportHint\">' + t('panel.importHint') + '</span>')\n      parts.push('</div>')\n      if (state.importOpen) {\n        parts.push('<div class=\"rss_importPaste\">')\n        parts.push('<textarea class=\"rss_input rss_importTextarea\" data-field=\"rss-import-text\" placeholder=\"' + esc(t('placeholder.importList')) + '&#10;阮一峰的网络日志, https://www.ruanyifeng.com/blog/atom.xml&#10;https://example.com/feed\">' + esc(state.importText) + '</textarea>')\n        parts.push('<button class=\"rss_btn\" data-action=\"custom-import-paste-go\">' + t('btn.import') + '</button>')\n        parts.push('</div>')\n      }\n      parts.push('<div id=\"rss-channel-list\">' + channelListHtml() + '</div>')\n      parts.push('</div>')\n      return parts.join('')\n    }\n\n    function updateChannels() {\n      updateSection('rss-sec-channels', renderChannelsSection())\n    }\n\n    function updateChannelList() {\n      const node = panelEl !== undefined ? panelEl.querySelector('#rss-channel-list') : null\n      if (node === null) return\n      node.innerHTML = channelListHtml()\n    }\n\n    function moveChannel(from, to) {\n      const sources = state.config?.sources\n      if (!sources || from === to || from < 0 || from >= sources.length || to < 0 || to >= sources.length) return\n      const [moved] = sources.splice(from, 1)\n      sources.splice(to, 0, moved)\n      updateChannels()\n      markDirty()\n      scheduleSave()\n    }\n\n    function handleChannelDragStart(event) {\n      if ((state.customQuery || '').trim()) return\n      const handle = event.target.closest ? event.target.closest('[data-drag-index]') : null\n      if (!handle) return\n      dragIndex = Number(handle.dataset.dragIndex)\n      const row = handle.closest('[data-channel-index]')\n      if (row) row.classList.add('rss_dragging')\n      if (event.dataTransfer) {\n        event.dataTransfer.effectAllowed = 'move'\n        try {\n          event.dataTransfer.setData('text/plain', String(dragIndex))\n        } catch {\n          /* 某些环境不允许 setData */\n        }\n      }\n    }\n\n    function handleChannelDragOver(event) {\n      if (dragIndex === null) return\n      const row = event.target.closest ? event.target.closest('[data-channel-index]') : null\n      if (!row) return\n      event.preventDefault()\n      if (event.dataTransfer) event.dataTransfer.dropEffect = 'move'\n    }\n\n    function handleChannelDrop(event) {\n      if (dragIndex === null) return\n      const row = event.target.closest ? event.target.closest('[data-channel-index]') : null\n      if (!row) return\n      event.preventDefault()\n      const toIndex = Number(row.dataset.channelIndex)\n      moveChannel(dragIndex, toIndex)\n      dragIndex = null\n    }\n\n    function handleChannelDragEnd() {\n      dragIndex = null\n      const dragging = panelEl !== undefined ? panelEl.querySelector('.rss_channelRow.rss_dragging') : null\n      if (dragging) dragging.classList.remove('rss_dragging')\n    }\n\n\n    function renderHeader() {\n      const parts = []\n      parts.push('<div class=\"rss_panelHeader\" id=\"rss-header\">')\n      parts.push('<h2 class=\"rss_panelTitle\">' + t('panel.title') + '</h2>')\n      if (state.dirty) {\n        parts.push('<span class=\"rss_dirtyChip\" title=\"' + esc(t('panel.unsavedTitle')) + '\">' + t('panel.unsaved') + '</span>')\n      }\n      parts.push('<div class=\"rss_toolbar\">')\n      parts.push('<button class=\"rss_btnGhost\" data-action=\"digest-refresh\"' + (state.refreshing ? ' disabled' : '') + '>' + (state.refreshing ? t('msg.refreshing') : t('btn.refresh')) + '</button>')\n      parts.push('<button class=\"rss_btnGhost\" data-action=\"config-reset\"' + (state.loading ? ' disabled' : '') + '>' + t('btn.discard') + '</button>')\n      parts.push('<button class=\"rss_btn\" data-action=\"config-save\" title=\"Ctrl / Cmd + S\"' + (state.saving ? ' disabled' : '') + '>' + (state.saving ? t('msg.saving') : t('btn.save')) + '</button>')\n      parts.push('</div>')\n      parts.push('</div>')\n      return parts.join('')\n    }\n\n    function renderErrorNode() {\n      if (!state.error) return '<div id=\"rss-error\"></div>'\n      return '<div id=\"rss-error\"><div class=\"rss_banner\" data-kind=\"error\">' + esc(state.error) + '</div></div>'\n    }\n\n    function renderDigestSection() {\n      const digest = state.digest\n      const parts = []\n      parts.push('<div class=\"rss_settingSection\" id=\"rss-sec-digest\">')\n      // 慢刷新才出过渡层（顶部进度条 + 「当前显示：08:12 生成」胶囊），绝对定位不推版\n      if (state.refreshing && state.refreshSlow && digest) parts.push(busyCardHtml(digest))\n      parts.push('<div class=\"rss_settingTitle\">' + t('panel.digest') + '</div>')\n      if (!digest) {\n        parts.push('<div class=\"rss_empty\">' + t('list.noDigest') + '</div>')\n      } else {\n        const items = digest.items || []\n        const sources = digest.sources || []\n        const errors = digest.errors || []\n        const meta = []\n        if (digest.date) meta.push(esc(digest.date))\n        meta.push(t('panel.entryCount', { count: items.length }))\n        if (sources.length > 0) meta.push(t('panel.feedCount', { count: sources.length }))\n        if (digest.generatedAt) meta.push(t('panel.generatedAt', { time: esc(fmtTime(digest.generatedAt)) }))\n        if (state.config?.dailyTime) meta.push(t('panel.dailyAt', { time: esc(state.config.dailyTime) }))\n        parts.push('<div class=\"rss_digestStats\">' + meta.join(' · ') + '</div>')\n        if (errors.length > 0) {\n          const preview = errors.slice(0, 2).map((e) => esc(e.source + ': ' + e.error)).join('; ')\n          parts.push('<div class=\"rss_banner\" data-kind=\"warn\">' + (preview ? t('msg.fetchFailedCountDetail', { count: errors.length, preview }) : t('msg.fetchFailedCount', { count: errors.length })) + (errors.length > 2 ? '…' : '') + '</div>')\n        }\n        // AI 摘要整体不可用 / 全部失败时也要让用户看见原因（部分失败在弹窗条目标注里可感知）\n        if (digest.aiSummary && (digest.aiSummary.reason || digest.aiSummary.failed > 0)) {\n          const aiText = digest.aiSummary.reason || t('msg.aiFallback', { count: digest.aiSummary.failed })\n          parts.push('<div class=\"rss_banner\" data-kind=\"warn\">' + esc(t('msg.aiError', { reason: aiText })) + '</div>')\n        }\n        if (items.length === 0) {\n          parts.push('<div class=\"rss_empty\">' + t('list.noDigestItems') + '</div>')\n        }\n        parts.push('<div class=\"rss_digestActions\">')\n        parts.push('<button class=\"rss_btnGhost\" data-action=\"digest-view\"' + (items.length === 0 ? ' disabled' : '') + '>' + t('btn.viewList') + '</button>')\n        parts.push('<button class=\"rss_btnGhost rss_btnIcon\" data-action=\"digest-refresh\"' + (state.refreshing ? ' disabled data-loading aria-busy=\"true\"' : '') + ' title=\"' + (state.refreshing ? t('msg.refreshing') : t('btn.refresh')) + '\" aria-label=\"' + esc(t('btn.refresh')) + '\">' + ICON_REFRESH + '</button>')\n        parts.push('<button class=\"rss_btnGhost rss_btnIcon\" data-action=\"digest-copy\"' + (items.length === 0 ? ' disabled' : '') + ' title=\"' + esc(t('btn.copyMarkdown')) + '\" aria-label=\"' + esc(t('btn.copyMarkdown')) + '\">' + ICON_COPY + '</button>')\n        parts.push('</div>')\n      }\n      parts.push('</div>')\n      return parts.join('')\n    }\n\n    function isSubscribed(url) {\n      return (state.config?.sources || []).some((source) => source.url === url)\n    }\n\n    function catalogToolsHtml() {\n      const entries = state.catalogEntries || []\n      const subscribed = entries.filter((entry) => isSubscribed(entry.url)).length\n      const selectedCount = entries.filter((entry) => state.catalogSelected.has(entry.url)).length\n      let html = '<div class=\"rss_catalogToolbar\" id=\"rss-catalog-tools\">'\n      html += '<span class=\"rss_catalogStats\">' + t('panel.catalogStats', { total: entries.length, subscribed, selected: selectedCount }) + '</span>'\n      html += '<button class=\"rss_btnGhost\" data-action=\"catalog-select-all\">' + t('btn.selectAll') + '</button>'\n      html += '<button class=\"rss_btnGhost\" data-action=\"catalog-clear\"' + (selectedCount === 0 ? ' disabled' : '') + '>' + t('btn.clear') + '</button>'\n      html += '<button class=\"rss_btn\" data-action=\"catalog-add-selected\"' + (selectedCount === 0 ? ' disabled' : '') + '>' + t('btn.addSelected') + (selectedCount > 0 ? ' (' + selectedCount + ')' : '') + '</button>'\n      html += '</div>'\n      return html\n    }\n\n    function renderCatalogResults() {\n      if (state.catalogError) {\n        return '<div class=\"rss_banner\" data-kind=\"error\">' + esc(state.catalogError) + '</div>'\n      }\n      if (state.catalogLoading) {\n        return '<div class=\"rss_loading\">' + t('list.loadingCatalog') + '</div>'\n      }\n      if (state.catalogDisabled) {\n        return '<div class=\"rss_empty\">' + t('list.catalogDisabled') + '</div>'\n      }\n      const entries = state.catalogEntries || []\n      if (entries.length === 0) {\n        return state.catalogQuery || state.catalogCategory\n          ? '<div class=\"rss_empty\">' + t('list.noMatchingFeeds') + '</div>'\n          : '<div class=\"rss_empty\">' + t('list.catalogIdle') + '</div>'\n      }\n      const parts = []\n      parts.push(catalogToolsHtml())\n      parts.push('<div class=\"rss_list\" id=\"rss-catalog-list\">')\n      for (let i = 0; i < entries.length; i++) {\n        const entry = entries[i]\n        const added = isSubscribed(entry.url)\n        parts.push('<div class=\"rss_item\">')\n        parts.push('<div class=\"rss_itemTop\">')\n        parts.push('<input type=\"checkbox\" data-action=\"catalog-toggle\" data-url=\"' + esc(entry.url) + '\" title=\"' + esc(t('btn.bulkSelect')) + '\"' + (added ? ' disabled' : '') + (state.catalogSelected.has(entry.url) ? ' checked' : '') + ' />')\n        parts.push('<div class=\"rss_itemMain\">')\n        const originName = entry.catalog || ''\n        parts.push('<div class=\"rss_itemTitle\">' + esc(entry.name) + ' <span class=\"rss_sourceChip\">' + esc(entry.category) + '</span><span class=\"rss_sourceChip rss_catalogOrigin\" title=\"' + esc(t('panel.fromCatalogTitle', { name: originName })) + '\">' + esc(t('panel.fromCatalog', { name: originName || t('panel.unknownCatalog') })) + '</span></div>')\n        parts.push('<div class=\"rss_itemMeta\">' + esc(entry.url) + '</div>')\n        parts.push('</div>')\n        parts.push('<button class=\"rss_linkBtn\" data-action=\"catalog-add\" data-index=\"' + i + '\"' + (added ? ' disabled' : '') + '>' + (added ? t('btn.added') : t('btn.add')) + '</button>')\n        parts.push('</div>')\n        parts.push('</div>')\n      }\n      parts.push('</div>')\n      return parts.join('')\n    }\n\n    function renderCatalogSection() {\n      const parts = []\n      parts.push('<div class=\"rss_settingSection\" id=\"rss-sec-catalog\">')\n      parts.push('<div class=\"rss_settingHint\">' + t('panel.catalogHintBefore') + '<a class=\"rss_linkBtn\" href=\"https://jackyst0.github.io/awesome-rsshub-routes/\" target=\"_blank\" rel=\"noreferrer\">awesome-rsshub-routes</a>' + t('panel.catalogHintAfter') + '</div>')\n      parts.push('<div id=\"rss-catalog-sources\">' + renderCatalogSourcesBlock() + '</div>')\n      parts.push('<div class=\"rss_addRow rss_catalogSearchRow\">')\n      parts.push('<input class=\"rss_input\" data-field=\"rss-catalog-query\" value=\"' + esc(state.catalogQuery) + '\" placeholder=\"' + esc(t('placeholder.catalogSearch')) + '\" autocomplete=\"off\" spellcheck=\"false\" />')\n      parts.push('<select class=\"rss_input\" data-field=\"rss-catalog-category\">' + catalogCategoryOptions() + '</select>')\n      parts.push('<select class=\"rss_input\" data-field=\"rss-catalog-source\">' + catalogSourceOptions() + '</select>')\n      parts.push('</div>')\n      parts.push('<div id=\"rss-catalog-results\">' + renderCatalogResults() + '</div>')\n      parts.push('</div>')\n      return parts.join('')\n    }\n\n    function renderCatalogSourcesBlock() {\n      const parts = []\n      parts.push('<div class=\"rss_catalogSources\">')\n      const builtin = state.catalogBuiltin\n      parts.push('<div class=\"rss_catalogSourceRow\">')\n      parts.push('<span class=\"rss_catalogSourceName\">' + t('panel.builtinSource', { name: builtin ? esc(builtin.name) : 'awesome-rsshub-routes' }) + '</span>')\n      parts.push('<span class=\"rss_catalogSourceMeta\">' + (builtin ? t('panel.entryCount', { count: builtin.entryCount }) : '…') + ' · ' + t('panel.fixed') + '</span>')\n      parts.push('<span class=\"rss_catalogSourceActions\"></span>')\n      parts.push('</div>')\n      const catalogs = state.config?.catalogs || []\n      const statusByUrl = new Map((state.catalogSources || []).map((source) => [source.url, source]))\n      for (const catalog of catalogs) {\n        const status = statusByUrl.get(catalog.url)\n        let meta\n        let stateText\n        if (status !== undefined) {\n          meta = 'title=\"' + esc(catalog.url) + (status.error ? esc(t('panel.errorDetail', { error: status.error })) : '') + '\"'\n          stateText = status.ok\n            ? t('panel.entryCount', { count: status.entryCount })\n            : '<span class=\"rss_catalogSourceError\">' + t('list.loadFailed') + '</span>' + (status.error ? ' · ' + esc(status.error) : '')\n        } else {\n          stateText = '<span class=\"rss_catalogSourcePending\">' + t('list.pendingSave') + '</span>'\n        }\n        parts.push('<div class=\"rss_catalogSourceRow\">')\n        parts.push('<span class=\"rss_catalogSourceName\" title=\"' + esc(catalog.name) + '\">' + esc(catalog.name) + '</span>')\n        parts.push('<span class=\"rss_catalogSourceMeta\" ' + (meta || 'title=\"' + esc(catalog.url) + '\"') + '>' + stateText + '</span>')\n        parts.push('<span class=\"rss_catalogSourceActions\"><button class=\"' + (status === undefined ? 'rss_btnGhost' : 'rss_btnGhost rss_btnDanger') + '\" data-action=\"catalog-remove-source\" data-url=\"' + esc(catalog.url) + '\">' + (status === undefined ? t('btn.cancel') : t('btn.remove')) + '</button></span>')\n        parts.push('</div>')\n      }\n      parts.push('<div class=\"rss_addRow rss_catalogAddRow\">')\n      parts.push('<input class=\"rss_input\" data-field=\"rss-catalog-new-name\" value=\"' + esc(state.catalogNewName) + '\" placeholder=\"' + esc(t('placeholder.catalogName')) + '\" />')\n      parts.push('<input class=\"rss_input\" data-field=\"rss-catalog-new-url\" value=\"' + esc(state.catalogNewUrl) + '\" placeholder=\"' + esc(t('placeholder.catalogUrl')) + '\" spellcheck=\"false\" />')\n      parts.push('<button class=\"rss_btnGhost\" data-action=\"catalog-add-source\">' + t('btn.addCatalog') + '</button>')\n      parts.push('</div>')\n      parts.push('</div>')\n      return parts.join('')\n    }\n\n    function renderCategoriesSection() {\n      const parts = []\n      parts.push('<div class=\"rss_settingSection\" id=\"rss-sec-categories\">')\n      parts.push('<div class=\"rss_settingTitle\">' + t('panel.categories') + '</div>')\n      parts.push('<div class=\"rss_settingHint\">' + t('panel.categoriesHint') + '</div>')\n      const categories = state.config?.categories || []\n      if (categories.length > 0) {\n        parts.push('<div class=\"rss_categories\">')\n        for (const category of categories) {\n          parts.push('<span class=\"rss_categoryChip\">' + esc(category) + '<button class=\"rss_categoryRemove\" data-action=\"config-remove-category\" data-value=\"' + esc(category) + '\" aria-label=\"' + esc(t('btn.removeCategory', { category })) + '\">' + ICON_CLOSE + '</button></span>')\n        }\n        parts.push('</div>')\n      } else {\n        parts.push('<div class=\"rss_empty\">' + t('list.noCategories') + '</div>')\n      }\n      parts.push('<div class=\"rss_addRow\">')\n      parts.push('<input class=\"rss_input\" data-field=\"rss-new-category\" value=\"' + esc(state.newCategory) + '\" placeholder=\"' + esc(t('placeholder.newCategory')) + '\" />')\n      parts.push('<button class=\"rss_btnGhost\" data-action=\"config-add-category\">' + t('btn.add') + '</button>')\n      parts.push('</div>')\n      parts.push('</div>')\n      return parts.join('')\n    }\n\n    function renderAggregateSection() {\n      const config = state.config\n      const parts = []\n      parts.push('<div class=\"rss_settingSection\" id=\"rss-sec-aggregate\">')\n      parts.push('<div class=\"rss_settingTitle\">' + t('panel.aggregate') + '</div>')\n      parts.push('<div class=\"rss_formGrid\">')\n      parts.push('<div class=\"rss_field\"><span class=\"rss_fieldLabel\">' + t('panel.maxPerSource') + '</span><input class=\"rss_input\" data-field=\"rss-max-items\" type=\"number\" min=\"1\" value=\"' + (config.maxItemsPerSource || 5) + '\" /></div>')\n      parts.push('<div class=\"rss_field\"><span class=\"rss_fieldLabel\">' + t('panel.maxTotal') + '</span><input class=\"rss_input\" data-field=\"rss-max-total\" type=\"number\" min=\"1\" value=\"' + (config.maxTotalItems || 30) + '\" /></div>')\n      parts.push('<div class=\"rss_field\"><span class=\"rss_fieldLabel\">' + t('panel.dailyTime') + '</span><input class=\"rss_input\" data-field=\"rss-daily-time\" type=\"time\" value=\"' + esc(config.dailyTime || '08:00') + '\" /></div>')\n      parts.push('</div>')\n      parts.push('<div class=\"rss_settingHint\">' + t('panel.aggregateHint') + '</div>')\n      parts.push('</div>')\n      return parts.join('')\n    }\n\n    function renderAiSection() {\n      const ai = state.config?.ai || {}\n      const parts = []\n      parts.push('<div class=\"rss_settingSection\" id=\"rss-sec-ai\">')\n      parts.push('<div class=\"rss_settingTitle\">' + t('panel.ai') + '</div>')\n      parts.push('<label class=\"rss_checkRow\"><input type=\"checkbox\" data-field=\"rss-ai-enabled\" ' + (ai.enabled === true ? 'checked' : '') + ' /> ' + t('panel.aiEnabled') + '</label>')\n      parts.push('<div class=\"rss_formGrid\">')\n      parts.push('<div class=\"rss_field\"><span class=\"rss_fieldLabel\">' + t('panel.aiProvider') + '</span><input class=\"rss_input\" data-field=\"rss-ai-provider\" value=\"' + esc(ai.provider || '') + '\" placeholder=\"' + esc(t('placeholder.aiModel')) + '\" autocomplete=\"off\" spellcheck=\"false\" /></div>')\n      parts.push('<div class=\"rss_field\"><span class=\"rss_fieldLabel\">' + t('panel.aiModel') + '</span><input class=\"rss_input\" data-field=\"rss-ai-model\" value=\"' + esc(ai.model || '') + '\" placeholder=\"' + esc(t('placeholder.aiModel')) + '\" autocomplete=\"off\" spellcheck=\"false\" /></div>')\n      parts.push('<div class=\"rss_field\"><span class=\"rss_fieldLabel\">' + t('panel.aiMaxItems') + '</span><input class=\"rss_input\" data-field=\"rss-ai-max-items\" type=\"number\" min=\"1\" max=\"50\" value=\"' + (ai.maxItems || 20) + '\" /></div>')\n      parts.push('</div>')\n      parts.push('<div class=\"rss_settingHint\">' + t('panel.aiHint') + '</div>')\n      parts.push('</div>')\n      return parts.join('')\n    }\n\n    /** 懒创建 state.config.ai：首次编辑 AI 字段时补上默认关闭的空壳。 */\n    function aiConfig() {\n      if (!state.config.ai) state.config.ai = { enabled: false }\n      return state.config.ai\n    }\n\n    function renderPluginSection() {\n      const config = state.config\n      const parts = []\n      parts.push('<div class=\"rss_settingSection\" id=\"rss-sec-plugin\">')\n      parts.push('<div class=\"rss_settingTitle\">' + t('panel.plugin') + '</div>')\n      parts.push('<label class=\"rss_checkRow\"><input type=\"checkbox\" data-field=\"rss-enabled\" ' + (config.enabled !== false ? 'checked' : '') + ' /> ' + t('panel.pluginEnabled') + '</label>')\n      parts.push('</div>')\n      return parts.join('')\n    }\n\n\n    function renderAll(container) {\n      panelEl = container\n      const parts = []\n      parts.push('<div class=\"rss_panel\">')\n      parts.push(renderHeader())\n      parts.push(renderErrorNode())\n      if (state.loading || !state.config) {\n        parts.push('<div class=\"rss_loading\">' + t('list.loading') + '</div>')\n      } else {\n        parts.push(renderPluginSection())\n        parts.push(renderDigestSection())\n        parts.push(renderChannelsSection())\n        parts.push(renderCategoriesSection())\n        parts.push(renderAggregateSection())\n        parts.push(renderAiSection())\n      }\n      parts.push('</div>')\n      container.innerHTML = parts.join('')\n    }\n\n    /* ================================ 区块更新 ================================ */\n\n    function updateSection(id, html) {\n      if (panelEl === undefined || !panelEl.isConnected) return\n      const node = panelEl.querySelector('#' + id)\n      if (node === null) return\n      node.outerHTML = html\n    }\n\n    function updateHeader() {\n      updateSection('rss-header', renderHeader())\n    }\n\n\n    function updateError() {\n      updateSection('rss-error', renderErrorNode())\n    }\n\n    function updateCatalogResults() {\n      const root = catalogRoot()\n      const node = root !== undefined ? root.querySelector('#rss-catalog-results') : null\n      if (node === null) return\n      node.innerHTML = renderCatalogResults()\n    }\n\n    function updateCatalogTools() {\n      const root = catalogRoot()\n      const node = root !== undefined ? root.querySelector('#rss-catalog-tools') : null\n      if (node === null) return\n      node.outerHTML = catalogToolsHtml()\n    }\n\n    function updateCustomList() {\n      updateChannelList()\n    }\n\n    function updateCatalogSelect() {\n      const root = catalogRoot()\n      const select = root !== undefined ? root.querySelector('[data-field=\"rss-catalog-category\"]') : null\n      if (select === null) return\n      select.innerHTML = catalogCategoryOptions()\n    }\n\n    function markDirty() {\n      if (state.dirty) return\n      state.dirty = true\n      updateHeader()\n    }\n\n    /* ================================ 弹窗 ================================ */\n\n    function siteFromFeedUrl(url) {\n      try {\n        return new URL(url).origin + '/'\n      } catch {\n        return ''\n      }\n    }\n\n    function sourceSiteMap(digest, config) {\n      const map = {}\n      for (const source of config?.sources || []) {\n        if (source && source.name && source.url) map[source.name] = siteFromFeedUrl(source.url)\n      }\n      for (const source of digest?.sources || []) {\n        if (source && source.name) map[source.name] = source.site || map[source.name] || ''\n      }\n      return map\n    }\n\n    function modalCategories() {\n      const set = new Set()\n      for (const item of state.digest?.items || []) {\n        set.add(item.category || t('panel.uncategorized'))\n      }\n      return Array.from(set)\n    }\n\n    function filteredModalItems() {\n      const query = (state.modalQuery || '').trim().toLowerCase()\n      const items = state.digest?.items || []\n      if (!query && !state.modalCategory) return items\n      return items.filter((item) => {\n        if (state.modalCategory && (item.category || t('panel.uncategorized')) !== state.modalCategory) return false\n        if (!query) return true\n        const hay = [item.title, item.aiSummary, item.summary, item.source, item.category].filter(Boolean).join(' ').toLowerCase()\n        return hay.includes(query)\n      })\n    }\n\n    function renderModalItems(items, sourceSites) {\n      if (!items || items.length === 0) return '<div class=\"rss_empty\">' + t('list.noItemsToday') + '</div>'\n      const sites = sourceSites || {}\n      const byCategory = {}\n      for (const item of items) {\n        const key = item.category || t('panel.uncategorized')\n        if (!byCategory[key]) byCategory[key] = []\n        byCategory[key].push(item)\n      }\n      const parts = []\n      for (const category of Object.keys(byCategory)) {\n        const bySource = {}\n        for (const item of byCategory[category]) {\n          const key = item.source || t('panel.uncategorized')\n          if (!bySource[key]) bySource[key] = []\n          bySource[key].push(item)\n        }\n        parts.push('<div class=\"rss_source\">')\n        parts.push('<div class=\"rss_sourceName\">' + esc(category) + '</div>')\n        for (const source of Object.keys(bySource)) {\n          const site = sites[source]\n          const siteLink = site\n            ? ' <a class=\"rss_linkBtn\" href=\"' + esc(site) + '\" target=\"_blank\" rel=\"noreferrer\">' + t('btn.viewMore') + '</a>'\n            : ''\n          parts.push('<div class=\"rss_subSource\">')\n          parts.push('<span>' + esc(source) + '</span>' + siteLink)\n          parts.push('</div>')\n          parts.push('<div class=\"rss_list\">')\n          for (const item of bySource[source]) {\n            const title = item.title || t('list.untitled')\n            const meta = []\n            if (item.date) meta.push(esc(String(item.date).slice(0, 10)))\n            parts.push('<div class=\"rss_item\">')\n            parts.push('<div class=\"rss_itemTop\">')\n            parts.push('<div class=\"rss_itemMain\">')\n            parts.push('<div class=\"rss_itemTitle\">' + (item.link\n              ? '<a href=\"' + esc(item.link) + '\" target=\"_blank\" rel=\"noreferrer\">' + esc(title) + '</a>'\n              : esc(title)) + (meta.length ? ' <span class=\"rss_itemMeta\">' + meta.join(' / ') + '</span>' : '') + '</div>')\n            // AI 摘要优先，无则退回原文摘要（两者都按 120 字截断展示）\n            const summary = item.aiSummary || item.summary\n            if (summary) {\n              const text = summary.length > 120 ? summary.slice(0, 120) + '…' : summary\n              parts.push('<div class=\"rss_itemSummary\">' + esc(text) + '</div>')\n            }\n            parts.push('</div>')\n            parts.push('</div>')\n            parts.push('</div>')\n          }\n          parts.push('</div>')\n        }\n        parts.push('</div>')\n      }\n      return parts.join('')\n    }\n\n    /**\n     * 筛选 + 动作行：搜索框、计数、复制 / 刷新，以及分类 chips。\n     * 它是 .rss_modal 的固定子项（不在滚动区里），所以列表怎么滚都看得见——\n     * 与 tty 的 SFTP 面板「路径输入 + 刷新/新建目录/上传」同一形态。\n     */\n    function renderModalFilter() {\n      const digest = state.digest\n      const total = digest ? (digest.items || []).length : 0\n      const visible = digest ? filteredModalItems().length : 0\n      const empty = !digest || total === 0\n      const cats = modalCategories()\n      const parts = []\n      parts.push('<div class=\"rss_modalFilter\">')\n      parts.push('<div class=\"rss_modalToolbar\">')\n      // 没有 digest 时不渲染搜索框（列表是空的，搜也没意义），只留动作\n      if (digest) {\n        parts.push('<input class=\"rss_input\" data-field=\"rss-modal-search\" value=\"' + esc(state.modalQuery) + '\" placeholder=\"' + esc(t('placeholder.modalSearch')) + '\" autocomplete=\"off\" spellcheck=\"false\" />')\n      }\n      parts.push('<span class=\"rss_modalCount\">' + (digest ? t('panel.visibleCount', { visible, total }) : '') + '</span>')\n      parts.push('<button class=\"rss_btnGhost rss_btnIcon\" data-action=\"modal-copy\"' + (empty ? ' disabled' : '') + ' title=\"' + esc(t('btn.copyMarkdown')) + '\" aria-label=\"' + esc(t('btn.copyMarkdown')) + '\">' + ICON_COPY + '</button>')\n      parts.push('<button class=\"rss_btnGhost rss_btnIcon\" data-action=\"modal-refresh\"' + (state.modalLoading ? ' disabled data-loading aria-busy=\"true\"' : '') + ' title=\"' + (state.modalLoading ? t('msg.refreshing') : t('btn.refresh')) + '\" aria-label=\"' + esc(t('btn.refresh')) + '\">' + ICON_REFRESH + '</button>')\n      parts.push('</div>')\n      if (cats.length > 1) {\n        parts.push('<div class=\"rss_modalChips\">')\n        parts.push('<button class=\"rss_modalChip' + (state.modalCategory === '' ? ' rss_modalChipActive' : '') + '\" data-action=\"modal-cat\" data-value=\"\">' + t('btn.all') + '</button>')\n        for (const cat of cats) {\n          parts.push('<button class=\"rss_modalChip' + (state.modalCategory === cat ? ' rss_modalChipActive' : '') + '\" data-action=\"modal-cat\" data-value=\"' + esc(cat) + '\">' + esc(cat) + '</button>')\n        }\n        parts.push('</div>')\n      }\n      parts.push('</div>')\n      return parts.join('')\n    }\n\n    /**\n     * 「正在刷新订阅源」的过渡层（0.3.1）：顶部 2px 不定长进度条 + 浮层胶囊。\n     *\n     * 与 dsh-docker 的切目标过渡同一套语言，三条理由也一样：\n     *   - **不推版**：两者都绝对定位。插进文档流会把标题与列表整块推下去；\n     *   - **有归属**：胶囊写「当前显示：08:12 生成」——刷新期间看到的是旧数据这件事\n     *     要说清楚，否则用户会以为刷新没生效；\n     *   - **不抢眼**：可见文案只两段（状态 · 归属），完整解释放 title。\n     * 只在**慢加载**（沿用 180ms 消抖）时出现，毫秒级请求不会闪。\n     */\n    /** 只取时钟 HH:MM：胶囊里写「生成于 14:25」比带日期的全量时间戳利落。 */\n    function clockText(iso) {\n      const date = new Date(iso)\n      if (Number.isNaN(date.getTime())) return ''\n      return String(date.getHours()).padStart(2, '0') + ':' + String(date.getMinutes()).padStart(2, '0')\n    }\n\n    /** 胶囊文案：可见部分只两段（状态 · 归属），完整解释进 title。 */\n    function busyText(digest) {\n      const stamp = digest && digest.generatedAt ? fmtTime(digest.generatedAt) : ''\n      const clock = digest && digest.generatedAt ? clockText(digest.generatedAt) : ''\n      const label = clock === ''\n        ? t('msg.refreshingFeeds')\n        : t('msg.refreshingFeedsAt', { clock })\n      // fmtTime 已经带了日期，不要再拼 digest.date（会变成「2026-09-14 2026/9/14 14:25」）\n      const full = t('msg.refreshingTitle')\n        + (stamp === '' ? '' : t('msg.refreshingTitleData', { stamp }))\n      return { label, full }\n    }\n\n    /** 顶部 2px 不定长进度条（绝对定位在容器顶边）。 */\n    function busyBarHtml() {\n      return '<div class=\"rss_busyBar\" aria-hidden=\"true\"></div>'\n    }\n\n    /** 胶囊本体（视觉由 CSS 按容器区分：弹窗行内 / 设置卡绝对定位）。 */\n    function busyPillHtml(digest) {\n      const { label, full } = busyText(digest)\n      // 层次与 docker 一致：状态与归属里的「值」用强调色，连接词压淡\n      const [head, tail] = label.split(' · ')\n      const text = tail === undefined\n        ? '<span class=\"rss_busyDim\">' + esc(head) + '</span>'\n        : '<span class=\"rss_busyDim\">' + esc(head) + ' · </span><strong>' + esc(tail) + '</strong>'\n      return '<div class=\"rss_busyPill\" title=\"' + esc(full) + '\" aria-busy=\"true\">' + ICON_REFRESH + text + '</div>'\n    }\n\n    /** 设置卡用：进度条 + 绝对定位胶囊（都挂在区块上）。 */\n    function busyCardHtml(digest) {\n      return busyBarHtml() + busyPillHtml(digest)\n    }\n\n    function renderModalBody() {\n      const digest = state.digest\n      const allItems = digest?.items || []\n      const items = filteredModalItems()\n      const parts = []\n      if (digest?.errors && digest.errors.length) {\n        parts.push('<div class=\"rss_banner\" data-kind=\"warn\">' + t('msg.fetchFailedList', { list: digest.errors.map((e) => esc(e.source + ': ' + e.error)).join('; ') }) + '</div>')\n      }\n      if (items.length === 0) {\n        parts.push('<div class=\"rss_empty\">' + (allItems.length === 0 ? t('list.noItemsToday') : t('list.noMatchingItems')) + '</div>')\n      } else {\n        parts.push(renderModalItems(items, sourceSiteMap(digest, state.config)))\n      }\n      return parts.join('')\n    }\n\n    /* ---------- 加载态：消抖 + 骨架屏 ---------- */\n\n    /**\n     * 超过这个时长仍未加载完，才允许出占位。\n     * GET /api/dsh-rss/digest 只是读 ~/.dsh/rss-digest/ 里的文件（毫秒级），不加消抖的话\n     * 骨架屏会闪一帧就被真内容替掉，比直接出内容更难受。\n     */\n    const LOADING_DEBOUNCE_MS = 180\n    let modalSlowTimer = null\n\n    function beginLoading() {\n      state.modalLoading = true\n      state.modalSlow = false\n      clearTimeout(modalSlowTimer)\n      modalSlowTimer = setTimeout(() => {\n        modalSlowTimer = null\n        if (!state.modalLoading) return\n        state.modalSlow = true\n        if (state.digest) {\n          // 有旧数据：只把 body 标记成「更新中」，绝不整树重渲染——重渲染会重置滚动位置、\n          // 打断正在输入的搜索框。慢刷新（>阈值）才需要这个提示。\n          const body = modalEl !== undefined ? modalEl.querySelector('.rss_modalBody') : null\n          if (body !== null) {\n            body.setAttribute('data-updating', '')\n            body.setAttribute('aria-busy', 'true')\n          }\n          /*\n           * 过渡层（进度条 + 胶囊）也是**只插入、不重渲染**：它俩是绝对定位的独立节点，\n           * 插进去不会动列表布局，正好绕开「重渲染会丢焦点/滚动」这个约束。\n           * （放在 renderDigestModal 里生成是不够的——这条路径根本不重渲染。）\n           */\n          const modal = modalEl !== undefined ? modalEl.querySelector('.rss_modal') : null\n          if (modal !== null && modal.querySelector('.rss_busyBar') === null) {\n            // 进度条 + 胶囊都挂在 .rss_modalFilter 上：条贴分类行下沿，胶囊骑线上居中\n            const filter = modal.querySelector('.rss_modalFilter')\n            if (filter !== null) filter.insertAdjacentHTML('beforeend', busyBarHtml() + busyPillHtml(state.digest))\n          }\n          return\n        }\n        // 没数据可显示：重渲染以淡入骨架\n        renderDigestModal()\n      }, LOADING_DEBOUNCE_MS)\n    }\n\n    function endLoading() {\n      clearTimeout(modalSlowTimer)\n      modalSlowTimer = null\n      state.modalLoading = false\n      state.modalSlow = false\n      // 收掉过渡层。整树重渲染的路径会自然清掉，这里覆盖「只插节点、不重渲染」那条。\n      if (modalEl !== undefined) {\n        for (const node of modalEl.querySelectorAll('.rss_busyBar, .rss_busyPill')) node.remove()\n      }\n    }\n\n    /**\n     * 骨架屏：4 张与 .rss_item 同形的卡片轮廓（标题条 + 两行摘要）。\n     * pending=true 时先渲染但保持透明——先占住高度（弹窗不会从矮变高跳一下），\n     * 等消抖阈值过了再去掉 data-pending 淡入，毫秒级请求就不会「闪一下骨架」。\n     */\n    function renderSkeleton(pending) {\n      const widths = [88, 72, 94, 66]\n      const parts = ['<div class=\"rss_skel\"' + (pending ? ' data-pending' : '') + ' aria-hidden=\"true\">']\n      for (const width of widths) {\n        parts.push('<div class=\"rss_skelCard\">')\n        parts.push('<div class=\"rss_skelLine\" style=\"width:' + width + '%\"></div>')\n        parts.push('<div class=\"rss_skelLine\" data-w=\"sm\" style=\"width:96%\"></div>')\n        parts.push('<div class=\"rss_skelLine\" data-w=\"sm\" style=\"width:58%\"></div>')\n        parts.push('</div>')\n      }\n      parts.push('</div>')\n      return parts.join('')\n    }\n\n    /**\n     * 整树重渲染弹窗。\n     * @param keepScroll 数据落地时保留列表滚动位置（刷新不该把用户读到一半的列表弹回顶部）。\n     *                   搜索/筛选触发的重渲染传 false。\n     */\n    function renderDigestModal(keepScroll = false) {\n      if (modalEl === undefined) return\n      const digest = state.digest\n      let content\n      let updating = false\n      if (digest) {\n        // 已有数据：刷新不清空列表（stale-while-revalidate），新数据回来整体替换。\n        // 原来这里会无条件换成「加载中…」，把看得好好的条目抹掉。\n        content = renderModalBody()\n        // 压暗同样要消抖：GET /digest 是毫秒级，打开弹窗时立刻压暗会出现\n        // 「列表出现 → 变淡几帧 → 恢复」的闪烁，只有慢加载才需要这个提示\n        updating = state.modalLoading && state.modalSlow\n      } else if (state.modalLoading) {\n        // 真没数据可显示：骨架先以透明态占位，过了消抖阈值才淡入（见 renderSkeleton）\n        content = renderSkeleton(!state.modalSlow)\n      } else {\n        content = '<div class=\"rss_empty\">' + t('list.noDigest') + '</div>'\n      }\n      if (state.error) {\n        content = '<div class=\"rss_banner\" data-kind=\"error\">' + esc(state.error) + '</div>' + content\n      }\n      const title = t('panel.digest') + (digest && digest.date ? ' · ' + esc(digest.date) : '')\n      // 重渲染会重建整棵 DOM，两样东西要还回去：\n      //  - 搜索框焦点/光标：刷新期间列表是活的，用户可能正在输入，落地时不能把人踢出去；\n      //  - 列表滚动位置（仅 keepScroll）：刷新落地不该把读到一半的列表弹回顶部。\n      //    筛选/搜索引起的重渲染传 false —— 那是换了内容，理应回到顶部。\n      const prevSearch = modalEl.querySelector('[data-field=\"rss-modal-search\"]')\n      const searchFocused = prevSearch !== null && document.activeElement === prevSearch\n      const caretPos = searchFocused ? prevSearch.selectionStart : null\n      const prevBody = keepScroll ? modalEl.querySelector('.rss_modalBody') : null\n      const prevScroll = prevBody !== null ? prevBody.scrollTop : 0\n      modalEl.innerHTML =\n        '<div class=\"rss_modalBackdrop\" data-action=\"modal-backdrop\">' +\n          '<div class=\"rss_modal\" role=\"dialog\" aria-modal=\"true\" aria-label=\"' + title + '\">' +\n            '<div class=\"rss_modalHeader\">' +\n              '<h3 class=\"rss_modalTitle\">' + title + '</h3>' +\n              '<button class=\"rss_modalClose\" data-action=\"modal-close\" aria-label=\"' + esc(t('btn.close')) + '\">' + ICON_CLOSE + '</button>' +\n            '</div>' +\n            renderModalFilter() +\n            // 过渡层（进度条 + 胶囊）在 renderModalFilter 里，绝对定位在 .rss_modalFilter 上；\n            // 正文照旧（stale-while-revalidate）\n            '<div class=\"rss_modalBody\"' + (updating ? ' data-updating aria-busy=\"true\"' : '')\n              // keepScroll=true 只出现在「数据落地」那次渲染（loadDigestModal / refreshDigestModal\n              // 的 finally），用它当落地信号做 8px 上滑淡入；搜索/筛选的重渲染不带这个标记\n              + (keepScroll ? ' data-landed' : '') + '>'\n              + content + '</div>' +\n          '</div>' +\n        '</div>'\n      const search = modalEl.querySelector('[data-field=\"rss-modal-search\"]')\n      if (search !== null) {\n        search.addEventListener('input', () => {\n          const caret = search.selectionStart\n          state.modalQuery = search.value\n          renderDigestModal()\n          const next = modalEl.querySelector('[data-field=\"rss-modal-search\"]')\n          if (next !== null) {\n            next.focus()\n            try {\n              next.setSelectionRange(caret, caret)\n            } catch {\n              /* 无 caret 的输入框忽略 */\n            }\n          }\n        })\n        if (searchFocused) {\n          search.focus()\n          if (caretPos !== null) {\n            try {\n              search.setSelectionRange(caretPos, caretPos)\n            } catch {\n              /* 无 caret 的输入框忽略 */\n            }\n          }\n        }\n      }\n      if (prevScroll > 0) {\n        const nextBody = modalEl.querySelector('.rss_modalBody')\n        if (nextBody !== null) nextBody.scrollTop = prevScroll\n      }\n    }\n\n    function openDigestModal() {\n      if (modalEl === undefined || !modalEl.isConnected) {\n        modalEl = document.createElement('div')\n        modalEl.className = 'rss_modalRoot'\n        document.body.appendChild(modalEl)\n      }\n      state.modalOpener = document.activeElement instanceof HTMLElement ? document.activeElement : null\n      modalEl.style.display = ''\n      beginLoading()\n      state.modalQuery = ''\n      state.modalCategory = ''\n      renderDigestModal()\n      bindModalKeys()\n      void loadDigestModal()\n      const closeBtn = modalEl.querySelector('[data-action=\"modal-close\"]')\n      if (closeBtn !== null) closeBtn.focus()\n    }\n\n    function closeDigestModal() {\n      if (modalEl !== undefined) modalEl.style.display = 'none'\n      const opener = state.modalOpener\n      if (opener !== null && opener.isConnected && typeof opener.focus === 'function') {\n        opener.focus()\n      }\n    }\n\n    function bindModalKeys() {\n      if (modalEl === undefined || modalEl.dataset.keysBound === '1') return\n      modalEl.dataset.keysBound = '1'\n      modalEl.addEventListener('keydown', (event) => {\n        if (event.key === 'Escape') {\n          event.stopPropagation()\n          closeDigestModal()\n          return\n        }\n        if (event.key !== 'Tab') return\n        const focusables = Array.from(modalEl.querySelectorAll('button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex=\"-1\"])'))\n        if (focusables.length === 0) return\n        const first = focusables[0]\n        const last = focusables[focusables.length - 1]\n        const active = document.activeElement\n        if (event.shiftKey) {\n          if (active === first || active === modalEl || active === null) {\n            event.preventDefault()\n            last.focus()\n          }\n        } else if (active === last) {\n          event.preventDefault()\n          first.focus()\n        }\n      })\n    }\n\n    async function loadDigestModal() {\n      beginLoading()\n      renderDigestModal()\n      try {\n        const [digestRes, configRes] = await Promise.all([\n          apiRequest(API.digest),\n          apiRequest(API.config),\n        ])\n        state.digest = digestRes\n        state.config = configRes.config || { sources: [], categories: [], maxItemsPerSource: 5, maxTotalItems: 30, dailyTime: '08:00' }\n        state.error = ''\n      } catch (error) {\n        state.error = error.message\n      } finally {\n        endLoading()\n        renderDigestModal(true)\n      }\n    }\n\n    async function refreshDigestModal() {\n      beginLoading()\n      renderDigestModal()\n      try {\n        const data = await apiRequest(API.refresh, { method: 'POST' })\n        state.digest = data\n        toast(t('msg.refreshed'), 'ok')\n      } catch (error) {\n        toast(error.message, 'error')\n      } finally {\n        endLoading()\n        renderDigestModal(true)\n      }\n    }\n\n    /* ================================ 侧边栏入口 ================================ */\n\n    const RSS_SIDEBAR_ICON = '<svg viewBox=\"0 0 16 16\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M4 12h.01M4 8a4 4 0 0 1 4 4M4 4a8 8 0 0 1 8 8\"/><circle cx=\"12\" cy=\"12\" r=\"1\" fill=\"currentColor\" stroke=\"none\"/></svg>'\n\n    /* ================================ 订阅源目录弹窗 ================================ */\n\n    function renderCatalogModalHtml() {\n      return '<div class=\"rss_modalBackdrop\" data-action=\"catalog-backdrop\">' +\n        '<div class=\"rss_modal rss_catalogModal\" role=\"dialog\" aria-modal=\"true\" aria-label=\"' + esc(t('panel.feedCatalog')) + '\">' +\n          '<div class=\"rss_modalHeader\">' +\n            '<h3 class=\"rss_modalTitle\">' + t('panel.feedCatalog') + '</h3>' +\n            '<button class=\"rss_modalClose\" data-action=\"catalog-close\" aria-label=\"' + esc(t('btn.close')) + '\">' + ICON_CLOSE + '</button>' +\n          '</div>' +\n          '<div class=\"rss_modalBody\">' + renderCatalogSection() + '</div>' +\n          '<div class=\"rss_modalFooter\">' +\n            '<span class=\"rss_modalCount\"></span>' +\n            '<button class=\"rss_btnGhost\" data-action=\"catalog-close\">' + t('btn.close') + '</button>' +\n          '</div>' +\n        '</div>' +\n      '</div>'\n    }\n\n    function renderCatalogModal() {\n      if (catalogModalEl === undefined) return\n      catalogModalEl.innerHTML = renderCatalogModalHtml()\n    }\n\n    function openCatalogModal() {\n      if (catalogModalEl === undefined || !catalogModalEl.isConnected) {\n        catalogModalEl = document.createElement('div')\n        catalogModalEl.className = 'rss_modalRoot'\n        document.body.appendChild(catalogModalEl)\n      }\n      state.catalogOpen = true\n      renderCatalogModal()\n      catalogModalEl.addEventListener('keydown', (event) => {\n        if (event.key === 'Escape') closeCatalogModal()\n      })\n      loadCatalog()\n      const search = catalogModalEl.querySelector('[data-field=\"rss-catalog-query\"]')\n      if (search !== null) search.focus()\n    }\n\n    function closeCatalogModal() {\n      state.catalogOpen = false\n      if (catalogModalEl !== undefined) {\n        catalogModalEl.remove()\n        catalogModalEl = undefined\n      }\n    }\n\n\n    function sidebarRoot() {\n      const column = document.querySelector('[data-pane=\"sidebar\"], [class*=\"sidebarCol\"]')\n      if (column === null) return undefined\n      return column.querySelector('[class*=\"logoRow\"]')?.parentElement ?? column.firstElementChild\n    }\n\n    function newSessionButton(root) {\n      const nested = root.querySelector('button[class*=\"newSession\"]')\n      if (nested !== null) return nested\n      for (const child of root.children) {\n        if (child.tagName === 'BUTTON') return child\n      }\n      return undefined\n    }\n\n    function createSidebarEntry() {\n      const entry = document.createElement('button')\n      entry.type = 'button'\n      entry.dataset.dshRssEntry = ''\n      entry.className = 'rss_sidebarEntry'\n      entry.setAttribute('aria-label', t('panel.digest'))\n      entry.title = t('panel.digest')\n      entry.innerHTML = '<span class=\"rss_sidebarEntryIcon\">' + RSS_SIDEBAR_ICON + '</span><span class=\"rss_sidebarEntryLabel\">' + t('panel.digest') + '</span>'\n      entry.addEventListener('click', () => {\n        openDigestModal()\n      })\n      return entry\n    }\n\n    /* ============================ 入口显隐闸门 ============================ */\n\n    /**\n     * 「今日值得读」入口的显隐：config 确认「插件已禁用」（enabled === false）后\n     * 收起，其余情况（含 config 拉取失败）保持显示。entryGate 由 apply 挂载期间\n     * 注入（null = 已卸载，迟到的缓存刷新不允许再把入口挂回来）；禁用瞬间已打开\n     * 的摘要弹窗一并收掉。\n     */\n    let entryGate = null\n    let entryVisible = false\n\n    function setEntryVisible(visible) {\n      entryVisible = visible\n      if (entryGate !== null) entryGate.set(visible)\n    }\n\n    /** 由 config 推进入口显隐：仅「确认 enabled:false」收起。 */\n    function syncEntryFromConfig(config) {\n      setEntryVisible(!(config !== null && typeof config === 'object' && config.enabled === false))\n    }\n\n    /** 挂载时预取一次配置：驱动入口显隐（打开面板时 load() 会再拉一次）。 */\n    async function primeConfig() {\n      try {\n        const res = await apiRequest(API.config)\n        state.config = res.config || state.config\n        syncEntryFromConfig(state.config)\n      } catch {\n        /* 挂载时宿主可能未就绪：入口先保持显示 */\n      }\n    }\n\n    function placeSidebarEntry(root, entry) {\n      const button = newSessionButton(root)\n      if (button === undefined) return false\n      if (entry.parentElement !== root) {\n        const row = button.closest('[class*=\"logoRow\"]')\n        const base = row !== null && row.parentElement === root ? row : button\n        const family = Array.from(root.children).filter((el) => el instanceof HTMLElement && el.matches('[data-dsh-rss-entry], [data-dsh-taskboard-entry], [data-dsh-ssh-entry]'))\n        if (family.length > 0) {\n          const last = family[family.length - 1]\n          root.insertBefore(entry, last.nextSibling)\n        } else {\n          root.insertBefore(entry, base.nextElementSibling)\n        }\n      }\n      return true\n    }\n\n    function mountSidebarEntry() {\n      if (typeof document !== 'undefined' && document.querySelector('[data-dsh-rss-entry]') !== null) return () => {}\n      const entry = createSidebarEntry()\n      let root\n      let placed = false\n\n      const tryPlace = () => {\n        if (root !== undefined && !root.isConnected) {\n          rootObserver.disconnect()\n          root = undefined\n          placed = false\n        }\n        if (placed) {\n          if (document.body.contains(entry)) return\n          rootObserver.disconnect()\n          root = undefined\n          placed = false\n        }\n        root ??= sidebarRoot()\n        if (root === undefined) return\n        placed = placeSidebarEntry(root, entry)\n        if (placed) {\n          rootObserver.observe(root, { childList: true, subtree: true })\n        }\n      }\n\n      const waitObserver = new MutationObserver(() => {\n        tryPlace()\n      })\n      waitObserver.observe(document.body, { childList: true, subtree: true })\n\n      const rootObserver = new MutationObserver(() => {\n        if (root === undefined || !root.isConnected) {\n          placed = false\n          tryPlace()\n          return\n        }\n        if (!root.contains(entry)) placed = placeSidebarEntry(root, entry)\n      })\n\n      tryPlace()\n      return () => {\n        waitObserver.disconnect()\n        rootObserver.disconnect()\n        entry.remove()\n      }\n    }\n\n    /* ================================ 输入委托（按需更新，不再整面板重建） ================================ */\n\n    const FIELD_HANDLERS = {\n      'rss-enabled': (el) => {\n        if (!state.config) return\n        state.config.enabled = el.checked\n        markDirty()\n      },\n      'rss-source-name': (el) => {\n        if (!state.config || el.dataset.index === undefined) return\n        const source = state.config.sources[Number(el.dataset.index)]\n        if (source) {\n          source.name = el.value\n          markDirty()\n        }\n      },\n      'rss-source-url': (el) => {\n        if (!state.config || el.dataset.index === undefined) return\n        const source = state.config.sources[Number(el.dataset.index)]\n        if (source) {\n          source.url = el.value\n          markDirty()\n        }\n      },\n      'rss-source-category': (el) => {\n        if (!state.config || el.dataset.index === undefined) return\n        const source = state.config.sources[Number(el.dataset.index)]\n        if (source) {\n          source.category = el.value || undefined\n          markDirty()\n        }\n      },\n      'rss-source-limit': (el) => {\n        if (!state.config || el.dataset.index === undefined) return\n        const source = state.config.sources[Number(el.dataset.index)]\n        if (source) {\n          const value = Number(el.value)\n          source.limit = Number.isFinite(value) && value > 0 ? value : undefined\n          markDirty()\n        }\n      },\n      'rss-builtin-category': (el) => {\n        if (!state.config) return\n        const key = el.dataset.key\n        const builtin = (state.builtins || []).find((item) => item.key === key)\n        if (!builtin) return\n        let entry = state.config.sources.find((source) => builtinOf(source)?.key === key)\n        if (!entry) {\n          entry = { name: builtin.name, url: builtin.url, builtin: builtin.key }\n          state.config.sources.push(entry)\n          const checkbox = panelEl !== undefined ? panelEl.querySelector('[data-action=\"builtin-toggle\"][data-key=\"' + key + '\"]') : null\n          if (checkbox !== null) checkbox.checked = true\n          updateChannels()\n        }\n        entry.category = el.value || undefined\n        markDirty()\n        scheduleSave()\n      },\n      'rss-new-category': (el) => {\n        state.newCategory = el.value\n      },\n      'rss-catalog-query': (el) => {\n        state.catalogQuery = el.value\n        scheduleCatalogLoad()\n      },\n      'rss-custom-query': (el) => {\n        state.customQuery = el.value\n        updateCustomList()\n      },\n      'rss-import-text': (el) => {\n        state.importText = el.value\n      },\n      'rss-import-file': (el) => {\n        const file = el.files && el.files[0]\n        if (!file) return\n        const reader = new FileReader()\n        reader.onload = () => importSourcesFromText(String(reader.result || ''), 'OPML', true)\n        reader.readAsText(file)\n        el.value = '' // 允许再次选择同一文件\n      },\n      'rss-catalog-category': (el) => {\n        state.catalogCategory = el.value\n        loadCatalog()\n      },\n      'rss-catalog-source': (el) => {\n        state.catalogSource = el.value\n        loadCatalog()\n      },\n      'rss-catalog-new-name': (el) => {\n        state.catalogNewName = el.value\n      },\n      'rss-catalog-new-url': (el) => {\n        state.catalogNewUrl = el.value\n      },\n      'rss-max-items': (el) => {\n        if (!state.config) return\n        const value = Number(el.value)\n        state.config.maxItemsPerSource = Number.isFinite(value) && value > 0 ? value : undefined\n        markDirty()\n      },\n      'rss-max-total': (el) => {\n        if (!state.config) return\n        const value = Number(el.value)\n        state.config.maxTotalItems = Number.isFinite(value) && value > 0 ? value : undefined\n        markDirty()\n      },\n      'rss-daily-time': (el) => {\n        if (!state.config) return\n        state.config.dailyTime = el.value\n        markDirty()\n      },\n      'rss-ai-enabled': (el) => {\n        if (!state.config) return\n        aiConfig().enabled = el.checked\n        markDirty()\n      },\n      'rss-ai-provider': (el) => {\n        if (!state.config) return\n        aiConfig().provider = el.value.trim()\n        markDirty()\n      },\n      'rss-ai-model': (el) => {\n        if (!state.config) return\n        aiConfig().model = el.value.trim()\n        markDirty()\n      },\n      'rss-ai-max-items': (el) => {\n        if (!state.config) return\n        const value = Number(el.value)\n        aiConfig().maxItems = Number.isFinite(value) && value > 0 ? Math.min(50, Math.round(value)) : undefined\n        markDirty()\n      },\n    }\n\n    function handleFieldEvent(event) {\n      const target = event.target\n      const el = target !== null && target.closest ? target.closest('[data-field^=\"rss-\"]') : null\n      if (el === null) return\n      const field = el.dataset.field\n      if (field === 'rss-modal-search') return\n      const handler = FIELD_HANDLERS[field]\n      if (typeof handler !== 'function') return\n      handler(el)\n    }\n\n    /* ================================ 数据操作 ================================ */\n\n    let catalogTimer = null\n\n    function scheduleCatalogLoad() {\n      clearTimeout(catalogTimer)\n      catalogTimer = setTimeout(loadCatalog, 250)\n    }\n\n    async function loadCatalog() {\n      state.catalogLoading = true\n      state.catalogError = ''\n      updateCatalogResults()\n      try {\n        const params = new URLSearchParams()\n        if (state.catalogQuery && state.catalogQuery.trim()) params.set('q', state.catalogQuery.trim())\n        if (state.catalogCategory) params.set('category', state.catalogCategory)\n        if (state.catalogSource) params.set('source', state.catalogSource)\n        const suffix = params.toString() ? '?' + params.toString() : ''\n        const data = await apiRequest(API.catalog + suffix)\n        state.catalogEntries = data.entries || []\n        state.catalogCategories = data.categories || state.catalogCategories\n        state.catalogSourceNames = data.sources || state.catalogSourceNames\n        state.catalogSources = data.catalogs || []\n        state.catalogBuiltin = data.builtin || null\n        state.catalogDisabled = data.disabled === true\n        updateCatalogSelect()\n        updateCatalogSources()\n      } catch (error) {\n        state.catalogError = error.message\n        state.catalogEntries = []\n      } finally {\n        state.catalogLoading = false\n        updateCatalogResults()\n      }\n    }\n\n    async function load() {\n      state.loading = true\n      state.error = ''\n      if (panelEl !== undefined) renderAll(panelEl)\n      try {\n        const [digestRes, configRes] = await Promise.all([\n          apiRequest(API.digest),\n          apiRequest(API.config),\n        ])\n        state.digest = digestRes\n        state.config = configRes.config || { sources: [], categories: [], maxItemsPerSource: 5, maxTotalItems: 30, dailyTime: '08:00' }\n        state.builtins = configRes.builtins || BUILTIN_CHANNELS\n        syncEntryFromConfig(state.config)\n      } catch (error) {\n        state.error = error.message\n      } finally {\n        state.loading = false\n        if (panelEl !== undefined) {\n          renderAll(panelEl)\n          loadCatalog()\n        }\n      }\n    }\n\n    async function refresh() {\n      state.refreshing = true\n      state.refreshSlow = false\n      state.error = ''\n      updateHeader()\n      updateError()\n      // 与弹窗同一套消抖：刷新是抓订阅源，通常不止 180ms，慢下来才给提示\n      clearTimeout(refreshSlowTimer)\n      refreshSlowTimer = setTimeout(() => {\n        refreshSlowTimer = null\n        if (!state.refreshing) return\n        state.refreshSlow = true\n        updateSection('rss-sec-digest', renderDigestSection())\n      }, LOADING_DEBOUNCE_MS)\n      try {\n        const data = await apiRequest(API.refresh, { method: 'POST' })\n        state.digest = data\n        toast(t('msg.refreshed'), 'ok')\n      } catch (error) {\n        state.error = error.message\n        toast(error.message, 'error')\n      } finally {\n        state.refreshing = false\n        state.refreshSlow = false\n        clearTimeout(refreshSlowTimer)\n        refreshSlowTimer = null\n        updateHeader()\n        updateError()\n        // 这一版渲染是「数据落地」→ 给区块加入场动画标记\n        updateSection('rss-sec-digest', renderDigestSection().replace('<div class=\"rss_settingSection\" id=\"rss-sec-digest\">', '<div class=\"rss_settingSection\" id=\"rss-sec-digest\" data-landed>'))\n      }\n    }\n\n    /** refreshSlow 的定时器（与弹窗的 modalSlowTimer 同构）。 */\n    let refreshSlowTimer = null\n\n\n    function scheduleSave(delay) {\n      clearTimeout(saveTimer)\n      saveTimer = setTimeout(() => {\n        saveTimer = undefined\n        if (state.saving) {\n          scheduleSave(200)\n          return\n        }\n        saveConfig()\n      }, delay || 500)\n    }\n\n    async function saveConfig() {\n      if (!state.config) return\n      clearTimeout(saveTimer)\n      saveTimer = undefined\n      state.saving = true\n      state.error = ''\n      updateHeader()\n      updateError()\n      try {\n        const data = await apiRequest(API.config, {\n          method: 'POST',\n          headers: { 'content-type': 'application/json' },\n          body: JSON.stringify({ config: state.config }),\n        })\n        state.config = data.config || state.config\n        state.builtins = data.builtins || BUILTIN_CHANNELS\n        state.newCategory = ''\n        state.dirty = false\n        syncEntryFromConfig(state.config)\n        // 服务端归一化后的 AI 配置可能与输入不同（不成对被忽略、数值夹紧），重渲染该区块\n        updateSection('rss-sec-ai', renderAiSection())\n        if (data.warnings && data.warnings.length > 0) {\n          toast(t('msg.savedWithWarnings', { warnings: data.warnings.join('; ') }), 'info')\n        } else {\n          toast(t('msg.saved'), 'ok')\n        }\n        await refresh()\n        loadCatalog()\n      } catch (error) {\n        state.error = error.message\n        toast(error.message, 'error')\n      } finally {\n        state.saving = false\n        updateHeader()\n        updateError()\n      }\n    }\n\n    async function copyText(text) {\n      const value = text || ''\n      if (!value) {\n        toast(t('msg.nothingToCopy'), 'error')\n        return\n      }\n      try {\n        await navigator.clipboard.writeText(value)\n        toast(t('msg.copied'), 'ok')\n      } catch {\n        try {\n          const textarea = document.createElement('textarea')\n          textarea.value = value\n          textarea.style.position = 'fixed'\n          textarea.style.opacity = '0'\n          document.body.appendChild(textarea)\n          textarea.select()\n          document.execCommand('copy')\n          textarea.remove()\n          toast(t('msg.copied'), 'ok')\n        } catch {\n          toast(t('msg.copyFailed'), 'error')\n        }\n      }\n    }\n\n    /* ================================ OPML / 批量导入导出 ================================ */\n\n    function hostnameOf(url) {\n      try {\n        return new URL(url).hostname.replace(/^www\\./, '')\n      } catch {\n        return url\n      }\n    }\n\n    function escXml(value) {\n      return String(value ?? '')\n        .replace(/&/g, '&amp;')\n        .replace(/</g, '&lt;')\n        .replace(/>/g, '&gt;')\n        .replace(/\"/g, '&quot;')\n        .replace(/'/g, '&apos;')\n    }\n\n    function parseOpmlFallback(text) {\n      const items = []\n      const re = /<outline\\b[^>]*>/gi\n      let match\n      while ((match = re.exec(text)) !== null) {\n        const tag = match[0]\n        const url = /xmlUrl\\s*=\\s*[\"']([^\"']+)[\"']/i.exec(tag)?.[1]\n        if (!url) continue\n        const name = (/text\\s*=\\s*[\"']([^\"']*)[\"']/i.exec(tag)?.[1] || /title\\s*=\\s*[\"']([^\"']*)[\"']/i.exec(tag)?.[1] || '').trim()\n        const category = (/category\\s*=\\s*[\"']([^\"']*)[\"']/i.exec(tag)?.[1] || '').trim()\n        if (!name) continue\n        try {\n          new URL(url)\n        } catch {\n          continue\n        }\n        items.push({ name, url, ...(category ? { category } : {}) })\n      }\n      return items\n    }\n\n    function parseOpmlText(text) {\n      if (typeof DOMParser !== 'undefined') {\n        try {\n          const doc = new DOMParser().parseFromString(text, 'text/xml')\n          const items = []\n          const outlines = doc.getElementsByTagName('outline')\n          for (const node of outlines) {\n            const url = node.getAttribute('xmlUrl')\n            if (!url) continue\n            const name = (node.getAttribute('text') || node.getAttribute('title') || '').trim()\n            const category = (node.getAttribute('category') || '').trim()\n            if (!name) continue\n            try {\n              new URL(url)\n            } catch {\n              continue\n            }\n            items.push({ name, url, ...(category ? { category } : {}) })\n          }\n          if (items.length > 0) return items\n        } catch {\n          /* 解析失败则走正则兜底 */\n        }\n      }\n      return parseOpmlFallback(text)\n    }\n\n    function parseUrlList(text) {\n      const items = []\n      for (const rawLine of text.split(/\\r?\\n/)) {\n        const line = rawLine.trim()\n        if (!line) continue\n        let name = ''\n        let url = line\n        const m = /^(.*?)[,，\\t ]+(https?:\\/\\/\\S+)$/i.exec(line)\n        if (m) {\n          name = m[1].trim()\n          url = m[2].trim()\n        }\n        try {\n          new URL(url)\n        } catch {\n          continue\n        }\n        items.push({ name: name || hostnameOf(url), url, category: '' })\n      }\n      return items\n    }\n\n    function mergeSources(items) {\n      const existing = new Set((state.config?.sources || []).map((source) => (source.url || '').trim().toLowerCase()))\n      let added = 0\n      let skipped = 0\n      for (const item of items) {\n        const key = (item.url || '').trim().toLowerCase()\n        if (!key || existing.has(key)) {\n          skipped += 1\n          continue\n        }\n        existing.add(key)\n        state.config.sources.push({\n          name: item.name || hostnameOf(item.url),\n          url: item.url.trim(),\n          ...(item.category ? { category: item.category } : {}),\n          limit: 5,\n        })\n        added += 1\n      }\n      return { added, skipped }\n    }\n\n    function importSourcesFromText(text, kind, autoSave) {\n      if (!text || !text.trim()) {\n        toast(t('msg.nothingToImport'), 'error')\n        return\n      }\n      const items = kind === 'OPML' ? parseOpmlText(text) : parseUrlList(text)\n      if (items.length === 0) {\n        toast(t('msg.importParseFailed'), 'error')\n        return\n      }\n      const result = mergeSources(items)\n      state.importOpen = false\n      state.importText = ''\n      updateChannels()\n      if (result.added === 0) {\n        toast(t('msg.noNewSources', { count: result.skipped }), 'info')\n        return\n      }\n      markDirty()\n      if (autoSave) {\n        toast(t('msg.importedSaving', { added: result.added, skipped: result.skipped > 0 ? t('msg.importSkipped', { count: result.skipped }) : '' }), 'info')\n        saveConfig()\n      } else {\n        toast(t('msg.importedPending', { added: result.added, skipped: result.skipped > 0 ? t('msg.importSkipped', { count: result.skipped }) : '' }), 'ok')\n      }\n    }\n\n    function buildOpml() {\n      const lines = []\n      lines.push('<?xml version=\"1.0\" encoding=\"UTF-8\"?>')\n      lines.push('<opml version=\"2.0\">')\n      lines.push('<head><title>' + t('msg.opmlTitle') + '</title></head>')\n      lines.push('<body>')\n      for (const source of state.config?.sources || []) {\n        const name = source.name || hostnameOf(source.url)\n        const cat = source.category || ''\n        lines.push('  <outline type=\"rss\" text=\"' + escXml(name) + '\" title=\"' + escXml(name) + '\"' + (cat ? ' category=\"' + escXml(cat) + '\"' : '') + ' xmlUrl=\"' + escXml(source.url) + '\"/>')\n      }\n      lines.push('</body>')\n      lines.push('</opml>')\n      return lines.join('\\n')\n    }\n\n    function exportOpml() {\n      const xml = buildOpml()\n      const blob = new Blob([xml], { type: 'application/xml' })\n      const url = URL.createObjectURL(blob)\n      const a = document.createElement('a')\n      a.href = url\n      a.download = 'dsh-rss-subscriptions.opml'\n      document.body.appendChild(a)\n      a.click()\n      a.remove()\n      setTimeout(() => URL.revokeObjectURL(url), 1000)\n      toast(t('msg.exportedCount', { count: state.config?.sources?.length || 0 }), 'ok')\n    }\n\n    /* ================================ 事件 ================================ */\n\n    function handleClick(event) {\n      const target = event.target\n      const el = target && target.closest ? target.closest('[data-action]') : null\n      if (!el) return\n      /*\n       * 作用域：只处理自己卡片 / 自己浮层里的点击。浮层（digest / catalog）挂在\n       * `document.body` 上、不在 panelEl 